describe('Deep Link Navigation', () => {
    beforeEach(() => {
        cy.visit('/');
    });

    it('should load the correct page when accessing a deep link directly', () => {
        cy.visit('/products/12345');
        cy.url().should('include', '/products/12345');
        cy.get('h1').should('contain', 'Product 12345');
    });

    it('should show a 404 page for an invalid deep link', () => {
        cy.visit('/products/invalid-id');
        cy.url().should('include', '/products/invalid-id');
        cy.get('h1').should('contain', '404 Not Found');
    });
});
